/* Same Bearer auth as Chat Retention; passes the request body through. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true, body: req.body || {} } }];

/* Error-rate alert check (priority 6, Langfuse-minimal).
   ALL data access via the n8n public API (helpers.httpRequest) — the same
   pattern as Chat Retention — because direct pg queries inside task-runner
   Code nodes crash the runner on any DatabaseError (read-only 'name' on the
   pg-protocol error object kills the runner process).

   Window: last ALERT_WINDOW_MIN minutes of chat_executions rows (fetched
   newest-first, filtered by createdAt in code). Fires an ops_alerts row when
   total >= ALERT_MIN_TOTAL and error rate >= ALERT_RATE_THRESHOLD, with
   ALERT_COOLDOWN_MIN cooldown. mode='list' returns recent alerts. */
const item = $input.first().json;
const body = item.body || {};
const mode = body.mode || 'check';

const WINDOW_MIN = Number($env.ALERT_WINDOW_MIN || 60);
const THRESHOLD = Number($env.ALERT_RATE_THRESHOLD || 0.5);
const MIN_TOTAL = Number($env.ALERT_MIN_TOTAL || 5);
const COOLDOWN_MIN = Number($env.ALERT_COOLDOWN_MIN || 60);
// B5: severity thresholds. critical means "stop what you are doing", info is a heads-up.
const SEV_CRITICAL = Number($env.ALERT_SEVERITY_CRITICAL || 0.8);
const API = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: API + path, headers: H, qs, body: payload });
const filterEq = (col, value) => JSON.stringify({ type: 'and', filters: [{ columnName: col, condition: 'eq', value }] });

/* Alert delivery — generic outbound webhook (env-configured).
   ALERT_WEBHOOK_FORMAT: generic | slack | discord | feishu */
const deliver = async (kind, message, extra) => {
  const fmt = String($env.ALERT_WEBHOOK_FORMAT || 'generic').toLowerCase();
  const text = '[PivotAI 告警] ' + kind + ' · ' + message;
  let url = '';
  let payload;
  if (fmt === 'telegram') {
    const tgToken = String($env.TELEGRAM_BOT_TOKEN || '').trim();
    const tgChat = String($env.TELEGRAM_CHAT_ID || '').trim();
    if (!tgToken || !tgChat) return 'skipped:no-channel';
    url = 'https://api.telegram.org/bot' + tgToken + '/sendMessage';
    payload = { chat_id: tgChat, text: text.slice(0, 4000), disable_web_page_preview: true };
  } else {
    url = String($env.ALERT_WEBHOOK_URL || '').trim();
    if (!url) return 'skipped:no-channel';
    if (fmt === 'slack' || fmt === 'discord') payload = { text };
    else if (fmt === 'feishu') payload = { msg_type: 'text', content: { text } };
    else payload = { kind, message, at: new Date().toISOString(), ...(extra || {}) };
  }
  try {
    await this.helpers.httpRequest({ method: 'POST', url, headers: { 'Content-Type': 'application/json' }, body: payload, timeout: 10000 });
    return 'ok';
  } catch (e) {
    return 'error:' + String(e && e.message ? e.message : e).slice(0, 140);
  }
};


try {
  const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
  const byName = {};
  for (const t of tables) byName[t.name] = t.id;
  const execId = byName['chat_executions'];
  const alertsId = byName['ops_alerts'];
  if (!execId || !alertsId) {
    return [{ json: { ok: false, mode, error: 'chat_executions / ops_alerts data tables missing (run deploy.mjs)' } }];
  }

  if (mode === 'list') {
    const rows = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 20, sortBy: 'createdAt:desc' })).data || [];
    return [{ json: { ok: true, mode, alerts: rows } }];
  }

  /* ---- B5 mode: silence — maintenance window, settable at runtime ----
     A silenced window still RECORDS alerts, it only stops delivery:
     suppressing noise must never mean losing history. */
  if (mode === 'silence') {
    const silenceId = byName['ops_alert_silence'];
    if (!silenceId) return [{ json: { ok: false, mode, error: 'ops_alert_silence table missing (run deploy.mjs)' } }];
    const act = String(body.action || 'list').toLowerCase();
    const all = (await api('GET', `/data-tables/${silenceId}/rows`, { limit: 50 })).data || [];
    const live = all.filter((r) => Date.parse(r.until || '') > Date.now());
    if (act === 'clear') {
      const filter = encodeURIComponent(JSON.stringify({ type: 'and', filters: [{ columnName: 'id', condition: 'gt', value: 0 }] }));
      await api('DELETE', `/data-tables/${silenceId}/rows/delete?filter=${filter}`);
      return [{ json: { ok: true, mode, action: 'clear', cleared: all.length } }];
    }
    if (act === 'set') {
      const minutes = Number(body.minutes || 0);
      const untilIso = body.until ? String(body.until) : new Date(Date.now() + (minutes > 0 ? minutes : 60) * 60000).toISOString();
      if (!Number.isFinite(Date.parse(untilIso))) return [{ json: { ok: false, mode, error: 'until must be ISO 8601, or pass minutes' } }];
      await api('POST', `/data-tables/${silenceId}/rows`, null, { data: [{ reason: String(body.reason || 'maintenance').slice(0, 200), until: untilIso }] });
      return [{ json: { ok: true, mode, action: 'set', until: untilIso } }];
    }
    return [{ json: { ok: true, mode, action: 'list', silenced: live.length > 0, windows: live } }];
  }

  // ---- mode: check ----
  // fetch newest chat_executions rows (data table rows API), filter window in code
  const rows = (await api('GET', `/data-tables/${execId}/rows`, { limit: 250, sortBy: 'createdAt:desc' })).data || [];
  const cutoff = Date.now() - WINDOW_MIN * 60000;
  let total = 0;
  let errors = 0;
  // Do NOT assume ordering: the rows API only honours sortBy when the colon is
  // percent-encoded, and silently returns insertion order (oldest first) otherwise.
  // Scan every fetched row instead of breaking on the first one outside the window.
  for (const row of rows) {
    const t = Date.parse(row.createdAt || '');
    if (!(t >= cutoff)) continue;
    // Only genuine self-check probes are excluded. 'unknown' used to be skipped too,
    // but real requests that send no session header are recorded as 'unknown' as well.
    if (row.session_id === 'selfcheck') continue;
    total += 1;
    if (row.status === 'error') errors += 1;
  }
  const rate = total > 0 ? errors / total : 0;

  let alertFired = false;
  let lastDelivery = null;
  let lastKind = null;
  let lastMessage = null;
  let skipReason = null;
  let lastSeverity = null;
  if (total >= MIN_TOTAL && rate >= THRESHOLD) {
    const lastRows = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 1, sortBy: 'createdAt:desc' })).data || [];
    const lastAt = lastRows.length ? Date.parse(lastRows[0].createdAt || '') || 0 : 0;
    if (Date.now() - lastAt >= COOLDOWN_MIN * 60000) {
      const message = '错误率 ' + (rate * 100).toFixed(1) + '%（' + errors + '/' + total + '，窗口 ' + WINDOW_MIN + ' 分钟）超过阈值 ' + (THRESHOLD * 100) + '%';
      lastKind = 'error_rate';
      lastMessage = message;
      await api('POST', `/data-tables/${alertsId}/rows`, null, { data: [{
        kind: 'error_rate',
        window_minutes: WINDOW_MIN,
        total,
        errors,
        error_rate: Math.round(rate * 1000) / 1000,
        threshold: THRESHOLD,
        message,
        severity: rate >= SEV_CRITICAL ? 'critical' : 'warn',
      }] });
      alertFired = true;
    } else {
      skipReason = 'cooldown';
    }
  } else if (total < MIN_TOTAL) {
    skipReason = 'below min total';
  }

  // embedding quota check (1M tokens per model; warn at 80%), API-based
  let quota = null;
  try {
    const mt = byName['kb_usage'];
    if (mt) {
      const cur = (await api('GET', `/data-tables/${mt}/rows`, { limit: 1 })).data || [];
      const used = Number(cur[0]?.total_embed_tokens || 0);
      const LIMIT = Number($env.EMBED_QUOTA_TOKENS || 1000000);
      quota = { used, limit: LIMIT, pct: Math.round((used / LIMIT) * 1000) / 10 };
      if (used / LIMIT >= 0.8) {
        const exists = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 20, sortBy: 'createdAt:desc' })).data || [];
        const lastQ = exists.find((r) => r.kind === 'embedding_quota');
        const recent = lastQ && (Date.now() - (Date.parse(lastQ.createdAt) || 0)) < 24 * 3600 * 1000;
        if (!recent) {
            lastKind = 'embedding_quota';
            lastMessage = '知识库 embedding 额度已用 ' + quota.pct + '%';
          await api('POST', `/data-tables/${alertsId}/rows`, null, { data: [{ kind: 'embedding_quota', window_minutes: 0, total: used, errors: 0, error_rate: used / LIMIT, threshold: 0.8, message: '知识库 embedding 额度已用 ' + quota.pct + '%（' + used + '/' + LIMIT + '），请提前购买加油包或考虑切换模型', severity: used / LIMIT >= 0.95 ? 'critical' : 'warn' }] });
          alertFired = true;
        }
      }
    }
  } catch (e) { /* quota check best-effort */ }

  /* ---- cost budget check: 24h model spend vs. a configured budget ----
     Reads the Chat Stats API instead of recomputing from `rows`: the console
     card and the alert must show the SAME number, and Stats scans 1000 rows
     while this workflow only fetched 250. Two levels: warn, then critical. */
  let cost = null;
  try {
    const WARN_USD = Number($env.ALERT_COST_24H_USD || 2);
    const CRIT_USD = Number($env.ALERT_COST_CRITICAL_USD || 5);
    const AUTH = ['Bea', 'rer '].join('') + String($env.CHAT_API_KEY || '');
    const st = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://localhost:5678/webhook/v1/stats/executions',
      headers: { Authorization: AUTH },
      timeout: 30000
    });
    const sc = (st && st.cost) || {};
    const spend = Number(sc.cost_24h_usd || 0);
    const r6 = (x) => Math.round(Number(x || 0) * 1e6) / 1e6;
    const top = Object.entries(sc.by_model || {})
      .sort((a, b) => Number(b[1]) - Number(a[1]))
      .slice(0, 3)
      .map((e) => e[0] + ' $' + Number(e[1]).toFixed(3));
    cost = {
      usd_24h: r6(spend),
      usd_7d: r6(sc.cost_7d_usd),
      usd_total: r6(sc.total_cost_usd),
      budget: WARN_USD,
      critical: CRIT_USD,
      pct: WARN_USD > 0 ? Math.round((spend / WARN_USD) * 1000) / 10 : null,
      top_models: top
    };
    if (WARN_USD > 0 && spend >= WARN_USD) {
      const sev = spend >= CRIT_USD ? 'critical' : 'warn';
      const exists = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 20, sortBy: 'createdAt:desc' })).data || [];
      const lastC = exists.find((r) => r.kind === 'cost_budget');
      const fresh = lastC && (Date.now() - (Date.parse(lastC.createdAt) || 0)) < 24 * 3600 * 1000;
      // 升级（warn -> critical）不受 24h 去重限制，否则预算翻倍了也不会再响
      const escalated = lastC && sev === 'critical' && lastC.severity !== 'critical';
      if (!fresh || escalated) {
        lastKind = 'cost_budget';
        lastSeverity = sev;
        lastMessage = '近 24h 模型花费 $' + spend.toFixed(4) + ' 超过预算阈值 $' + WARN_USD +
          '（' + cost.pct + '%）' + (top.length ? ' · 主要来源 ' + top.join('、') : '');
        await api('POST', `/data-tables/${alertsId}/rows`, null, { data: [{
          kind: 'cost_budget',
          window_minutes: 1440,
          total: Number((st && st.totals && st.totals.total) || 0),
          errors: 0,
          error_rate: 0,
          threshold: WARN_USD,
          message: lastMessage,
          severity: sev
        }] });
        alertFired = true;
      } else {
        skipReason = skipReason || 'cost:recent';
      }
    }
  } catch (e) { /* cost check best-effort */ }

  if (alertFired && lastKind) {
    /* B5: maintenance window — record the alert, skip only the notification */
    let silenced = false;
    try {
      const sid = byName['ops_alert_silence'];
      if (sid) {
        const w = (await api('GET', `/data-tables/${sid}/rows`, { limit: 50 })).data || [];
        silenced = w.some((r) => Date.parse(r.until || '') > Date.now());
      }
    } catch (e) { /* silence check best-effort: fail OPEN, i.e. still deliver */ }
    if (silenced) {
      lastDelivery = 'silenced:maintenance';
    } else {
      lastDelivery = await deliver(lastKind, String(lastMessage || ''), { window_minutes: WINDOW_MIN });
    }
    /* annotate the most recent alert row with delivery status */
    try {
      const rr = (await api('GET', `/data-tables/${alertsId}/rows`, { limit: 1, sortBy: 'createdAt:desc' })).data || [];
      const rid = rr[0] && rr[0].id;
      if (rid) await api('PATCH', `/data-tables/${alertsId}/rows/update`, null, { filter: { type: 'and', filters: [{ columnName: 'id', condition: 'eq', value: rid }] }, data: { delivered: lastDelivery } });
    } catch (e) { /* best effort */ }
  }

return [{ json: {
    ok: true,
    mode: 'check',
    window_minutes: WINDOW_MIN,
    total,
    errors,
    error_rate: Math.round(rate * 1000) / 1000,
    threshold: THRESHOLD,
    min_total: MIN_TOTAL,
    alert_fired: alertFired,
    ...(skipReason ? { skip_reason: skipReason } : {}),
    ...(quota ? { embedding_quota: quota } : {}),
    ...(lastDelivery ? { delivery: lastDelivery } : {}),
    ...(cost ? { cost } : {}),
    ...(lastKind ? { severity: lastSeverity || (lastKind === 'embedding_quota' ? 'warn' : (Math.round(rate * 1000) / 1000 >= SEV_CRITICAL ? 'critical' : 'warn')) } : {}),
    checked_at: new Date().toISOString(),
  } }];
} catch (e) {
  return [{ json: { ok: false, mode, error: String(e && e.message ? e.message : e).slice(0, 300) } }];
}
